import openpyxl, zipfile, shutil, re, os

path='seed_collection_0080_unit_mismatch_9728_input.xlsx'
# Load formulas and compute cached values for all formula cells
wbf=openpyxl.load_workbook(path, data_only=False)
ws=wbf['1101']

# Build dict of constant numeric values from sheet
values={}
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
    for c in row:
        if isinstance(c.value,(int,float)):
            values[c.coordinate]=c.value
        elif c.value is None:
            values[c.coordinate]=0  # treat blank as 0 for arithmetic
# For formula cells, store formula string
formulas={}
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
    for c in row:
        if isinstance(c.value,str) and c.value.startswith('='):
            formulas[c.coordinate]=c.value[1:]  # without '='

# For computations, formula cells initially no values; compute recursively with memo
computed={}

def getval(ref):
    if ref in computed:
        return computed[ref]
    return values.get(ref, 0.0)

def eval_formula(text):
    # text without leading '='
    if text in computed:
        return computed[text] if text in computed else None
    f=text.strip()
    # SUM range
    m=re.match(r'SUM\(([A-Z]+\d+):([A-Z]+\d+)\)$', f, re.I)
    if m:
        r1=m.group(1); r2=m.group(2)
        # parse row/col
        col1=re.match(r'[A-Z]+', r1).group(0); row1=int(re.search(r'\d+', r1).group(0))
        col2=re.match(r'[A-Z]+', r2).group(0); row2=int(re.search(r'\d+', r2).group(0))
        # support single column ranges only
        from openpyxl.utils import column_index_from_string
        c1=column_index_from_string(col1); c2=column_index_from_string(col2)
        total=0.0
        for rr in range(row1,row2+1):
            for cc in range(c1,c2+1):
                coord=ws.cell(rr,cc).coordinate
                total += getval(coord)
        return total
    # simple arithmetic with + or - or / and maybe parentheses
    # Recursive parentheses removal and operators
    # Tokenize cell refs and numbers
    def eval_simple(s):
        s=s.strip()
        # remove surrounding parentheses if match entire expr
        while s.startswith('(') and s.endswith(')'):
            # ensure matching outer
            depth=0; ok=True
            for i,ch in enumerate(s):
                if ch=='(': depth+=1
                elif ch==')': depth-=1
                if depth==0 and i<len(s)-1:
                    ok=False; break
            if ok:
                s=s[1:-1].strip()
            else:
                break
        # Find top-level + or - (not inside parentheses), from right for left-to-right? We only have binary
        depth=0; op_idx=-1; op=None
        for i,ch in enumerate(s):
            if ch=='(': depth+=1
            elif ch==')': depth-=1
            elif depth==0 and ch in '+-':
                # skip if at start (unary)
                if i==0: continue
                op_idx=i; op=ch
        if op_idx>=0:
            left=eval_simple(s[:op_idx])
            right=eval_simple(s[op_idx+1:])
            return left+right if op=='+' else left-right
        # Find top-level / or *
        depth=0; op_idx=-1; op=None
        for i,ch in enumerate(s):
            if ch=='(': depth+=1
            elif ch==')': depth-=1
            elif depth==0 and ch in '/*':
                op_idx=i; op=ch
        if op_idx>=0:
            left=eval_simple(s[:op_idx])
            right=eval_simple(s[op_idx+1:])
            if op=='/':
                return left/right if right!=0 else 0
            else:
                return left*right
        # If cell reference
        m2=re.fullmatch(r'\$?([A-Z]{1,3})\$?(\d+)', s)
        if m2:
            return getval(m2.group(1)+m2.group(2))
        try:
            return float(s)
        except:
            return 0.0
    return eval_simple(f)

# Compute in order of columns/rows; formulas reference formulas in same or earlier cells mostly H then totals
# Sort by row then column maybe
for coord in sorted(formulas.keys(), key=lambda x: (int(re.search(r'\d+', x).group(0)), x)):
    val=eval_formula(formulas[coord])
    computed[coord]=val
    print(coord, formulas[coord], '=>', val)

# Now inject cached values into XML for all formula cells
# Read xlsx as zip and modify sheet1.xml
tmp_path=path+'.tmp'
# extract sheet1.xml content from original zip
zin=zipfile.ZipFile(path,'r')
xml=zin.read('xl/worksheets/sheet1.xml').decode('utf-8')
zin.close()

def replace_v(match):
    ref=match.group(1)
    if ref in computed:
        val=computed[ref]
        # format value similar to Excel; use repr for float but avoid numpy? use str
        if isinstance(val,float) and val.is_integer():
            val_str=str(int(val))
        else:
            val_str=str(val)
        return f'<c r="{ref}"{match.group(2)}><f>{match.group(3)}</f><v>{val_str}</v>'
    return match.group(0)

# Pattern for formula cells: <c r="REF" attrs><f>formula</f><v /></c>
pattern=re.compile(r'<c r="([A-Z]+\d+)"([^>]*)><f>(.*?)</f><v\s*/>', re.S)
new_xml, n=pattern.subn(replace_v, xml)
print('replaced', n)
# ensure all formula cells matched
for coord in formulas:
    if f'<c r="{coord}"' in new_xml:
        pass
# Write to a new zip preserving all entries
zout_path=path+'.new'
with zipfile.ZipFile(path,'r') as zin, zipfile.ZipFile(zout_path,'w', zipfile.ZIP_DEFLATED) as zout:
    for item in zin.infolist():
        data=zin.read(item.filename)
        if item.filename=='xl/worksheets/sheet1.xml':
            data=new_xml.encode('utf-8')
        zout.writestr(item, data)
